package ca.brtalgo.uberwatcher;
import android.app.Notification;import android.os.Bundle;import android.service.notification.NotificationListenerService;import android.service.notification.StatusBarNotification;import java.util.Locale;
public class UberNotificationListener extends NotificationListenerService{public void onNotificationPosted(StatusBarNotification s){if(s==null||s.getPackageName()==null)return;String p=s.getPackageName().toLowerCase(Locale.US);if(!(p.equals("com.ubercab.driver")||p.startsWith("com.uber")||p.contains("ubercab")))return;Notification n=s.getNotification();if(n==null||n.extras==null)return;Bundle e=n.extras;String t=String.valueOf(e.getCharSequence(Notification.EXTRA_TITLE,""));String x=String.valueOf(e.getCharSequence(Notification.EXTRA_TEXT,""));String b=String.valueOf(e.getCharSequence(Notification.EXTRA_BIG_TEXT,""));String a=(t+" "+x+" "+b).toLowerCase(Locale.US);if(a.contains("opportun")||a.contains("reservation")||a.contains("airport")||a.contains("flight")||a.contains("trip radar")||a.contains("boost")||a.contains("quest")||a.contains("promo")){String body=b.length()>0?b:x;AlertHelper.notify(this,"NEW UBER OPPORTUNITY",body.length()>0?body:"Uber posted a possible opportunity.");}}}
